import { cubicBezier, motion } from "framer-motion";
import React, { Fragment, useEffect } from "react";
import { FileText } from "lucide-react";
import { FaChevronDown } from "react-icons/fa";
import { Menu, Transition } from "@headlessui/react";
import { useSidebar } from "../Context/context";
import { IoCheckmark, IoCheckmarkDone } from "react-icons/io5";

interface MessageProps {
  message: {
    id: number;
    text: string;
    sender: "sender" | "receiver";
    time: string;
    file?:
      | {
          name: string;
          type: string;
          url: any;
          width?: number;
          height?: number;
        }
      | undefined;
  };
  isOwnMessage: boolean;
  isNewestMessage: boolean;
  setNewestMessageId: (id: number | null) => void;
  handleEdit: (msg: MessageProps["message"]) => void;
  handleCopy: (msg: MessageProps["message"]) => void;
  handleDelete: (msgId: number) => void;
}

const easing = cubicBezier(0.35, 0.17, 0.3, 0.86);

const Message: React.FC<MessageProps> = ({
  message,
  isOwnMessage,
  isNewestMessage,
  setNewestMessageId,
  handleEdit,
  handleCopy,
  handleDelete,
}) => {
  const isEmojiOnly = /^<img src=".*?" alt="emoji".*?>$/.test(message.text);
  const isImage = message.file && message.file.type.startsWith("image/");
  const isPdf = message.file && message.file.type === "application/pdf";
  const { setIsmodel, setSelectedImage } = useSidebar();
  const openImageModal = (imgUrl: string) => {
    setSelectedImage(imgUrl);
    setIsmodel(true);
  };

  useEffect(() => {
    if (isNewestMessage) {
      setTimeout(() => {
        setNewestMessageId(null);
      }, 1000);
    }
  }, [isNewestMessage, setNewestMessageId]);

  return (
    <motion.div
      initial={
        isNewestMessage
          ? {
              opacity: 0,
              y: isOwnMessage ? 250 : -250,
              x: isOwnMessage ? -250 : 250,
            }
          : {}
      }
      animate={isNewestMessage !== null ? { opacity: 1, y: 0, x: 0 } : {}}
      transition={
        isNewestMessage !== null ? { duration: 0.5, ease: easing } : {}
      }
      className={`flex flex-col relative w-full ${
        isOwnMessage ? "justify-end items-end" : "justify-start items-start"
      } my-7`}
    >
      {isEmojiOnly ? (
        <span
          dangerouslySetInnerHTML={{ __html: message.text }}
          className="w-20 h-20 block object-center object-cover"
        ></span>
      ) : isPdf ? (
        <div className="p-3 w-fit rounded-lg max-w-[75%] shadow-md bg-gray-100 flex items-center gap-3">
          <FileText className="text-red-500 w-8 h-8" />
          <div>
            <p className="text-sm font-medium text-gray-800">
              {message.file?.name}
            </p>
            <a
              href={message.file?.url}
              target="_blank"
              rel="noopener noreferrer"
              className="text-blue-500 underline text-sm"
            >
              Open PDF
            </a>
          </div>
        </div>
      ) : message.file ? (
        <div className="w-fit rounded-lg max-w-[75%] shadow-md  text-black">
          <a
            onClick={() => openImageModal(message.file!.url)}
            target="_blank"
            rel="noopener noreferrer"
          >
            <img
              src={message.file?.url}
              alt={message.file?.name || "Uploaded file"}
              className="rounded"
              style={{
                maxWidth: message.file?.width
                  ? `${message.file.width}px`
                  : "200px",
                maxHeight: message.file?.height
                  ? `${message.file.height}px`
                  : "200px",
              }}
            />
          </a>
        </div>
      ) : (
        <Menu
          as="div"
          className="relative group cursor-pointer rounded-lg bg-blue-500"
        >
          <Menu.Button className="p-3 cursor-pointer items-center transition-all text-white ease-linear duration-200 gap-2 flex justify-between w-fit  max-w-[75%] shadow-md  ">
            <p
              className="text-sm"
              dangerouslySetInnerHTML={{ __html: message.text }}
            ></p>
            <span className="hidden group-hover:block text-xs transition-all ease-linear duration-200 text-gray-300 ">
              <FaChevronDown />
            </span>
          </Menu.Button>
          <Transition
            as={Fragment}
            enter="transition ease-out duration-100"
            enterFrom="transform opacity-0 scale-95"
            enterTo="transform opacity-100 scale-100"
            leave="transition ease-in duration-75"
            leaveFrom="transform opacity-100 scale-100"
            leaveTo="transform opacity-0 scale-95"
          >
            <Menu.Items className="absolute z-[99] right-0 mt-2 w-48 origin-top-right divide-y divide-gray-100 rounded-md bg-[#2A2A36] shadow-lg ring-1 ring-black/5 focus:outline-none text-white">
              <div className="px-1 py-1">
                <Menu.Item>
                  {({ active }) => (
                    <button
                      onClick={() => handleCopy(message)}
                      className={`${
                        active
                          ? "bg-gradient-to-r from-blue-500 to-indigo-500  text-white"
                          : ""
                      } group flex w-full items-center rounded-md px-2 py-2 text-sm`}
                    >
                      Copy
                    </button>
                  )}
                </Menu.Item>
                <Menu.Item>
                  {({ active }) => (
                    <button
                      onClick={() => handleEdit(message)}
                      className={`${
                        active
                          ? "bg-gradient-to-r from-yellow-500 to-orange-500 text-white"
                          : ""
                      } group flex w-full items-center rounded-md px-2 py-2 text-sm`}
                    >
                      Edit
                    </button>
                  )}
                </Menu.Item>
                <Menu.Item>
                  {({ active }) => (
                    <button
                      onClick={() => handleDelete(message.id)}
                      className={`${
                        active
                          ? "bg-gradient-to-r from-red-600 to-red-400 text-white"
                          : ""
                      } group flex w-full items-center rounded-md px-2 py-2 text-sm`}
                    >
                      Delete
                    </button>
                  )}
                </Menu.Item>
              </div>
            </Menu.Items>
          </Transition>
        </Menu>
      )}
      <div className="flex items-center gap-1 text-xs text-gray-300 mt-1 text-right">
        <p className="">{message.time}</p>
        <span>
          {true ? (
            <IoCheckmarkDone />
          ) : true ? (
            <IoCheckmark />
          ) : (
            <IoCheckmarkDone color="blue" />
          )}
        </span>
      </div>
    </motion.div>
  );
};

export default Message;
